/bin/zsh -lc "node -e '
\"use strict\"
const Range = require(\"./classes/range\")
const Comparator = require(\"./classes/comparator\")
const intersects = require(\"./ranges/intersects\")
const satisfies = require(\"./functions/satisfies\")
console.log(\"runtime\", process.version)
const check = (name, fn) => { try { console.log(name, JSON.stringify(fn())) } catch (e) { console.log(name, e.name + \": \" + e.message, e.stack.split(\"\\n\").slice(1,4).join(\" | \")) } }
check(\"OR prerelease\", () => {
 const v = \"1.2.3-alpha\"
 const a = new Range(\"*\"), b = new Range(v), combined = new Range(\"* || \" + v)
 return {a:a.test(v), b:b.test(v), expected:true, observed:combined.test(v), normalized:combined.range, includePrerelease:new Range(\"* || \"+v,{includePrerelease:true}).test(v), releaseControl:combined.test(\"1.2.3\")}
})
check(\"Comparator input prerelease\", () => new Range(new Comparator(\">=1.2.3-alpha\")).test(\"1.2.3-beta\"))
check(\"Comparator string control\", () => new Range(\">=1.2.3-alpha\").test(\"1.2.3-beta\"))
check(\"Comparator includePrerelease\", () => new Range(new Comparator(\"\"), {includePrerelease:true}).test(\"1.2.3-alpha\"))
check(\"Comparator input stable control\", () => new Range(new Comparator(\">=1.2.3\")).test(\"1.2.4\"))
check(\"intersection shared witness\", () => {
 const a = \">=1.0.0-alpha <2.0.0\", b = \"1.0.0-beta\", v=b
 return {a:satisfies(v,a), b:satisfies(v,b), expected:true, observed:intersects(a,b), reversed:intersects(b,a), includePrerelease:intersects(a,b,{includePrerelease:true})}
})
check(\"intersection empty discrete gap\", () => {
 const a=\">1.0.0\", b=\"<1.0.1\"
 return {expected:false, observed:intersects(a,b), reversed:intersects(b,a), controlNonempty:intersects(a,\"<=1.0.1\"), prereleaseRejected:satisfies(\"1.0.1-alpha\",a)&&satisfies(\"1.0.1-alpha\",b)}
})
check(\"hyphen metadata includePrerelease\", () => {
 const options={includePrerelease:true}, v=\"1.2.3-alpha\"
 const bare=new Range(\"1.2.3 - 2.0.0\",options), built=new Range(\"1.2.3+build - 2.0.0\",options)
 return {bare:bare.range, built:built.range, expected:bare.test(v), observed:built.test(v), releaseControl:built.test(\"1.2.3\")}
})
check(\"tilde documented equivalence\", () => {
 const options={includePrerelease:true}, v=\"1.2.0-alpha\"
 return [\"~1.2\",\"1.2.x\",\">=1.2.0 <1.3.0-0\"].map(r=>({r, normalized:new Range(r,options).range, accepts:satisfies(v,r,options)}))
})
'"

