/bin/zsh -lc "node -e '
const Range = require(\"./classes/range\")
const Comparator = require(\"./classes/comparator\")
const satisfies = require(\"./functions/satisfies\")
const intersects = require(\"./ranges/intersects\")
console.log(\"runtime\", process.version)
function probe(label, f) {
  try { console.log(label, JSON.stringify(f())) } catch (e) { console.log(label, e.name + \": \" + e.message) }
}
for (const r of [\"1.2.3-alpha\", \"*\", \"* || 1.2.3-alpha\", \"1.2.3-alpha || *\"]) {
  probe(\"OR \" + r, () => { const a = new Range(r); return { parsed: a.range, pre: a.test(\"1.2.3-alpha\"), stable: a.test(\"1.2.3\") } })
}
for (const input of [\">=1.2.3-alpha\", \">=1.2.3\"]) {
  for (const v of [\"1.2.3\", \"1.2.3-beta\"]) {
    probe(\"comparator \" + input + \" / \" + v, () => new Range(new Comparator(input)).test(v))
    probe(\"string \" + input + \" / \" + v, () => new Range(input).test(v))
  }
}
probe(\"comparator includePrerelease\", () => new Range(new Comparator(\">=1.2.3\"), { includePrerelease: true }).test(\"1.2.4-beta\"))
probe(\"satisfies comparator\", () => satisfies(\"1.2.3-beta\", new Comparator(\">=1.2.3-alpha\")))
for (const [a,b,opts] of [
  [\">1.0.0 <1.0.1\", \"*\", undefined],
  [\">1.0.0 <1.0.1\", \"*\", {includePrerelease:true}],
  [\">=1.0.0-alpha <1.0.0\", \">=1.0.0-beta <1.0.0\", undefined],
  [\"1.0.0-alpha\", \">=1.0.0-alpha <1.0.0\", undefined],
]) probe(\"intersection \"+a+\" / \"+b+\" / \"+JSON.stringify(opts), () => intersects(a,b,opts))
'"

